export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
}

export function filterProducts(products: Product[], search: string, category: string): Product[] {
  const searchClean = search.trim().toLowerCase();
  return products.filter(product => {
    const categoryMatch = category === "All" || product.category === category;
    const searchMatch = searchClean === "" || product.name.toLowerCase().includes(searchClean);
    return categoryMatch && searchMatch;
  });
}

export function sortProducts(products: Product[], sortOrder: string): Product[] {
  if (!sortOrder) return products;

  const sorted = [...products];

  sorted.sort((a, b) => {
    if (sortOrder === "name-asc") {
      const nameA = a.name.toLowerCase();
      const nameB = b.name.toLowerCase();
      return nameA < nameB ? -1 : nameA > nameB ? 1 : 0;
    } else if (sortOrder === "name-desc") {
      const nameA = a.name.toLowerCase();
      const nameB = b.name.toLowerCase();
      return nameA > nameB ? -1 : nameA < nameB ? 1 : 0;
    } else if (sortOrder === "price-asc") {
      return a.price - b.price;
    } else if (sortOrder === "price-desc") {
      return b.price - a.price;
    }
    return 0;
  });

  return sorted;
}
